public static class AiProfile
{
    public const string Station = "АКЖТ";
    /// <summary>Пример вопроса про маршрут с названиями (окно помощника, подсказки).</summary>
    public const string RouteExampleRu = "маршрут Н на путь 3";
    public const string RouteExampleKk = "Н-нан 3 жолға маршрут";

    /// <summary>Пример в справке «как задать маршрут» (щелчок светофора, затем пути).</summary>
    public const string HelpExampleRu = "светофор Н, затем путь I.";
    public const string HelpExampleKk = "Н светофоры, содан кейін I жол.";

    /// <summary>Чей объект схемы: у АКЖТ Id с приставкой «А:», остальное — путевой пост.</summary>
    public static string StationOf(string id, AiLang l) => id.Contains(':') ? "АКЖТ" : l == AiLang.Kk ? "жол бекеті" : "путевой пост";

    public const string HelpLines = @"
переезд, извещение на переезд, закрытие переезда | Переезд (на путевом посту): лампа ЗП — белая, переезд открыт; мигает — закрывается; красная — закрыт. «Извещение» — переезд закрывается перед поездом, «Закрытие» — закрыть сразу. | Өтпе жол (жол бекетінде): ЗП шамы — ақ, ашық; жыпылықтайды — жабылып жатыр; қызыл — жабық. «Извещение» — пойыз алдында өтпе жол жабылады, «Закрытие» — бірден жабу.
проверка ламп, проверка, лампы по одной, шамдарды тексеру | «Проверка» — все лампы светофоров на 1,5 с загораются (проверка макета). «Лампы по одной» (инженерный режим) — на макете горит только выбранная лампа: так проверяют проводку светофоров. | «Проверка» — барлық бағдаршам шамдары 1,5 секундқа жанады (макетті тексеру). «Лампы по одной» (инженерлік режим) — макетте тек таңдалған шам жанады: бағдаршам сымдарын осылай тексереді.
arduino, макет, порт, датчики, плата, нет соединения | Вверху слева выберите COM-порт платы Arduino. Строка «Датчики» показывает, что присылают датчики занятости (пин 10 — Н-М1, пин 8 — УII). Без платы всё работает: стрелки переводятся только на экране, поезда — виртуальные. | Жоғарғы сол жақтан Arduino платасының COM-портын таңдаңыз. «Датчики» жолы бос еместік датчиктері не жіберетінін көрсетеді (10-пин — Н-М1, 8-пин — УII). Платасыз да бәрі жұмыс істейді: стрелкалар тек экранда ауысады, пойыздар — виртуалды.
связь, сервер, соседняя станция, алгабас, байланыс | Кнопка «Связь…» — связь со станцией Алгабас через сервер: занятость перегона, светофоры соседа, согласие на смену направления, передача поездов. | «Связь…» батырмасы — сервер арқылы Алгабас станциясымен байланыс: перегонның бос еместігі, көршінің светофорлары, бағытты ауыстыруға келісім, пойыздарды беру.
вид, обе схемы, один монитор | Кнопка «Вид»: обе схемы / только АКЖТ / только путевой пост — удобно на одном мониторе. | «Вид» батырмасы: екі сызба / тек АКЖТ / тек жол бекеті — бір мониторда ыңғайлы.
жи, ии, помощник, көмекші, что умеешь | Я — ИИ-помощник. Спросите: как задать маршрут (можно с названиями: «маршрут Н на путь 3»), для чего светофор Н1, что за стрелка 5/7, почему не задаётся маршрут, что такое автоблокировка. Наведите мышь на объект и спросите «что это?». Отвечаю по-русски или қазақша. | Мен — ЖИ-көмекшімін. Сұраңыз: маршрутты қалай беру керек (атаулармен де болады: «Н-нан 3 жолға маршрут»), Н1 светофоры не үшін, 5/7 стрелкасы қандай, маршрут неге берілмейді, автоблокировка деген не. Тінтуірді объектіге апарып, «бұл не?» деп сұраңыз. Орысша немесе қазақша жауап беремін.
";
}
